def runs(I,r,c,bg):
    # horizontal run containing (r,c) if I[r][c]!=bg, else None; length and whether run extends both ways
    if I[r][c]==bg: return None
    L=c
    while L>0 and I[r][L-1]==I[r][c]: L-=1
    R=c
    while R<len(I[r])-1 and I[r][R+1]==I[r][c]: R+=1
    return (R-L+1, L>0, R<len(I[r])-1)
def vrun(I,r,c,bg):
    if I[r][c]==bg: return None
    U=r
    while U>0 and I[U-1][c]==I[r][c]: U-=1
    D=r
    while D<len(I)-1 and I[D+1][c]==I[r][c]: D+=1
    return (D-U+1, U>0, D<len(I)-1)
