def seg_len(gi, r, c):
    bg = gi[0][0]
    L = c
    while L - 1 >= 0 and gi[r][L] != bg:
        L -= 1
    R = c
    while R + 1 < len(gi[r]) and gi[r][R] != bg:
        R += 1
    U = r
    while U - 1 >= 0 and gi[U][c] != bg:
        U -= 1
    D = r
    while D + 1 < len(gi) and gi[D][c] != bg:
        D += 1
    return (c - L, R - c, D - r, r - U)

